// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *AppBuild) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := AppBuildTableName
	siftCompany := ""
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		"App_Build$Primary", tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range appBuildSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, AppBuildTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, AppBuildTableName, keys)
}

// appBuildSIFTSpecs are the table's keys with sum_index_fields
func appBuildSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *AppBuild) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := AppBuildTableName, ""
	var results []sift.VerifyResult
	for _, spec := range appBuildSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, AppBuildTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: AppBuildTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, AppBuildTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

