// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *AppBuild) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *AppBuild) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var entry_noVal int
		if v, exists := pkMap["entry_no"]; exists {
			switch val := v.(type) {
			case int:
				entry_noVal = val
			case float64:
				entry_noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					entry_noVal = n
				}
			}
		}
		return t.GetByPK(entry_noVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case int:
		return t.GetByPK(pk)
	case float64:
		return t.GetByPK(int(pk))
	case string:
		var intVal int
		if _, err := fmt.Sscanf(pk, "%d", &intVal); err == nil {
			return t.GetByPK(intVal)
		}
	}

	fmt.Printf("Error: Invalid primary key type for App_Build.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *AppBuild) GetByPK(entry_no int) bool {
	tableName := AppBuildTableName
	var entry_noVal int
	var statusInt int
	var base_versionNull sql.NullString
	var triggerInt int
	var requested_byNull sql.NullString
	var requested_atNull sql.NullString
	var started_atNull sql.NullString
	var finished_atNull sql.NullString
	var appsNull sql.NullString
	var build_listVal []byte
	var logVal []byte
	var binary_sha256Null sql.NullString
	var bundle_pathNull sql.NullString
	var error_messageNull sql.NullString

	// Collect arguments for query
	args := []interface{}{
		entry_no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT entry_no, status, base_version, trigger, requested_by, requested_at, started_at, finished_at, apps, build_list, log, binary_sha256, bundle_path, error_message FROM "%s" WHERE 1=1 AND entry_no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&entry_noVal,
		&statusInt,
		&base_versionNull,
		&triggerInt,
		&requested_byNull,
		&requested_atNull,
		&started_atNull,
		&finished_atNull,
		&appsNull,
		&build_listVal,
		&logVal,
		&binary_sha256Null,
		&bundle_pathNull,
		&error_messageNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get App_Build: %v\n", err)
		return false
	}

	// Populate fields
	t.Entry_no = entry_noVal
	t.Status = AppBuildStatus(statusInt)
	t.Base_version = types.NewText(base_versionNull.String)
	t.Trigger = AppBuildTrigger(triggerInt)
	t.Requested_by = types.NewCode(requested_byNull.String)
	t.Requested_at, _ = types.NewDateTimeFromString(requested_atNull.String)
	t.Started_at, _ = types.NewDateTimeFromString(started_atNull.String)
	t.Finished_at, _ = types.NewDateTimeFromString(finished_atNull.String)
	t.Apps = types.NewText(appsNull.String)
	t.Build_list = build_listVal
	t.Log = logVal
	t.Binary_sha256 = types.NewText(binary_sha256Null.String)
	t.Bundle_path = types.NewText(bundle_pathNull.String)
	t.Error_message = types.NewText(error_messageNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *AppBuild) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := AppBuildTableName

	// Collect arguments for INSERT
	args := []interface{}{
		t.Entry_no,
		t.Status,
		t.Base_version,
		t.Trigger,
		t.Requested_by,
		t.Requested_at,
		t.Started_at,
		t.Finished_at,
		t.Apps,
		t.Build_list,
		t.Log,
		t.Binary_sha256,
		t.Bundle_path,
		t.Error_message,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (entry_no, status, base_version, trigger, requested_by, requested_at, started_at, finished_at, apps, build_list, log, binary_sha256, bundle_path, error_message) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (entry_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert App_Build: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(AppBuildTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *AppBuild) InsertAll(records []*AppBuild, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Entry_no,
			r.Status,
			r.Base_version,
			r.Trigger,
			r.Requested_by,
			r.Requested_at,
			r.Started_at,
			r.Finished_at,
			r.Apps,
			r.Build_list,
			r.Log,
			r.Binary_sha256,
			r.Bundle_path,
			r.Error_message,
		})
	}
	tableName := AppBuildTableName
	columns := []string{"entry_no", "status", "base_version", "trigger", "requested_by", "requested_at", "started_at", "finished_at", "apps", "build_list", "log", "binary_sha256", "bundle_path", "error_message"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *AppBuild) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("entry_no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := AppBuildTableName

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("entry_no") {
			setClauses = append(setClauses, "entry_no = ?")
			values = append(values, t.Entry_no)
		}
		if t.hasFieldChanged("status") {
			setClauses = append(setClauses, "status = ?")
			values = append(values, t.Status)
		}
		if t.hasFieldChanged("base_version") {
			setClauses = append(setClauses, "base_version = ?")
			values = append(values, t.Base_version)
		}
		if t.hasFieldChanged("trigger") {
			setClauses = append(setClauses, "trigger = ?")
			values = append(values, t.Trigger)
		}
		if t.hasFieldChanged("requested_by") {
			setClauses = append(setClauses, "requested_by = ?")
			values = append(values, t.Requested_by)
		}
		if t.hasFieldChanged("requested_at") {
			setClauses = append(setClauses, "requested_at = ?")
			values = append(values, t.Requested_at)
		}
		if t.hasFieldChanged("started_at") {
			setClauses = append(setClauses, "started_at = ?")
			values = append(values, t.Started_at)
		}
		if t.hasFieldChanged("finished_at") {
			setClauses = append(setClauses, "finished_at = ?")
			values = append(values, t.Finished_at)
		}
		if t.hasFieldChanged("apps") {
			setClauses = append(setClauses, "apps = ?")
			values = append(values, t.Apps)
		}
		if t.hasFieldChanged("build_list") {
			setClauses = append(setClauses, "build_list = ?")
			values = append(values, t.Build_list)
		}
		if t.hasFieldChanged("log") {
			setClauses = append(setClauses, "log = ?")
			values = append(values, t.Log)
		}
		if t.hasFieldChanged("binary_sha256") {
			setClauses = append(setClauses, "binary_sha256 = ?")
			values = append(values, t.Binary_sha256)
		}
		if t.hasFieldChanged("bundle_path") {
			setClauses = append(setClauses, "bundle_path = ?")
			values = append(values, t.Bundle_path)
		}
		if t.hasFieldChanged("error_message") {
			setClauses = append(setClauses, "error_message = ?")
			values = append(values, t.Error_message)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "status = ?")
		values = append(values, t.Status)
		setClauses = append(setClauses, "base_version = ?")
		values = append(values, t.Base_version)
		setClauses = append(setClauses, "trigger = ?")
		values = append(values, t.Trigger)
		setClauses = append(setClauses, "requested_by = ?")
		values = append(values, t.Requested_by)
		setClauses = append(setClauses, "requested_at = ?")
		values = append(values, t.Requested_at)
		setClauses = append(setClauses, "started_at = ?")
		values = append(values, t.Started_at)
		setClauses = append(setClauses, "finished_at = ?")
		values = append(values, t.Finished_at)
		setClauses = append(setClauses, "apps = ?")
		values = append(values, t.Apps)
		setClauses = append(setClauses, "build_list = ?")
		values = append(values, t.Build_list)
		setClauses = append(setClauses, "log = ?")
		values = append(values, t.Log)
		setClauses = append(setClauses, "binary_sha256 = ?")
		values = append(values, t.Binary_sha256)
		setClauses = append(setClauses, "bundle_path = ?")
		values = append(values, t.Bundle_path)
		setClauses = append(setClauses, "error_message = ?")
		values = append(values, t.Error_message)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["entry_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Entry_no)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND entry_no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify App_Build: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *AppBuild) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "entry_no":
		if old, ok := oldValue.(int); ok {
			return t.Entry_no != old
		}
		return true // Type mismatch, assume changed
	case "status":
		if old, ok := oldValue.(AppBuildStatus); ok {
			return t.Status != old
		}
	case "base_version":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Base_version.Equal(old)
		}
	case "trigger":
		if old, ok := oldValue.(AppBuildTrigger); ok {
			return t.Trigger != old
		}
	case "requested_by":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Requested_by.Equal(old)
		}
	case "requested_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Requested_at.Equal(old)
		}
	case "started_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Started_at.Equal(old)
		}
	case "finished_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Finished_at.Equal(old)
		}
	case "apps":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Apps.Equal(old)
		}
	case "build_list":
		// Skip comparison for BLOB fields (too large, use always modified)
		return true
	case "log":
		// Skip comparison for BLOB fields (too large, use always modified)
		return true
	case "binary_sha256":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Binary_sha256.Equal(old)
		}
	case "bundle_path":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Bundle_path.Equal(old)
		}
	case "error_message":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Error_message.Equal(old)
		}
	}

	return false
}

